import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useGameStore } from '../store/useGameStore';
import {
  ChevronDown,
  ChevronRight,
  LayoutDashboard,
  Users,
  Briefcase,
  DollarSign,
  Cpu,
  Globe,
  ShieldCheck,
  Megaphone,
  Phone
} from 'lucide-react';

interface NavItem {
  name: string;
  path: string;
  offline: boolean;
}

interface NavSection {
  role: string;
  title: string;
  icon: React.ReactNode;
  items: NavItem[];
}

const Navigation: React.FC = () => {
  const location = useLocation();
  const { isOnline } = useGameStore();
  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({
    'CEO': true // CEO section open by default
  });

  const sections: NavSection[] = [
    {
      role: 'CEO',
      title: 'Executive Suite',
      icon: <LayoutDashboard size={18} />,
      items: [
        { name: 'Dashboard', path: '/dashboard', offline: true },
        { name: 'News Feed', path: '/ceo/news', offline: true },
        { name: 'Agency Overview', path: '/ceo/overview', offline: true },
        { name: 'The Red Phone', path: '/ceo/hotline', offline: true },
      ]
    },
    {
      role: 'CHRO',
      title: 'Human Capital',
      icon: <Users size={18} />,
      items: [
        { name: 'Staff Roster', path: '/staff', offline: true },
        { name: '1:21 Meetings', path: '/chro/meetings', offline: true },
        { name: 'Agency Summit', path: '/chro/summit', offline: true },
      ]
    },
    {
      role: 'COO',
      title: 'Operations',
      icon: <Briefcase size={18} />,
      items: [
        { name: 'Active Missions', path: '/missions', offline: true },
        { name: 'World Map', path: '/coo/map', offline: true },
        { name: 'Ops Statistics', path: '/coo/stats', offline: true },
      ]
    },
    {
      role: 'CFO',
      title: 'Finances',
      icon: <DollarSign size={18} />,
      items: [
        { name: 'Sponsorships', path: '/cfo/sponsors', offline: true },
        { name: 'Weekly Review', path: '/cfo/review', offline: true },
        { name: 'Payroll', path: '/cfo/payroll', offline: true },
      ]
    },
    {
      role: 'CTO',
      title: 'R & D',
      icon: <Cpu size={18} />,
      items: [
        { name: 'Training Modules', path: '/cto/training', offline: true },
        { name: 'Gear & Gadgets', path: '/cto/gear', offline: true },
      ]
    },
    {
      role: 'CMO',
      title: 'Market & PR',
      icon: <Megaphone size={18} />,
      items: [
        { name: 'Recruitment', path: '/market', offline: true },
        { name: 'Brand Intelligence', path: '/cmo/market', offline: false },
      ]
    },
    {
      role: 'CLO',
      title: 'Legal & Heat',
      icon: <ShieldCheck size={18} />,
      items: [
        { name: 'Captivity Desk', path: '/clo/legal', offline: true },
        { name: 'Heat Management', path: '/clo/heat', offline: true },
      ]
    }
  ];

  const toggleSection = (role: string) => {
    setExpandedSections(prev => ({
      ...prev,
      [role]: !prev[role]
    }));
  };

  return (
    <nav className="flex flex-col gap-2 pb-10">
      {sections.map((section) => (
        <div key={section.role} className="flex flex-col">
          <button
            onClick={() => toggleSection(section.role)}
            className="flex items-center justify-between px-3 py-2 text-gray-400 hover:text-white hover:bg-hitman-black/30 rounded transition-colors group"
          >
            <div className="flex items-center gap-3">
              <span className="text-hitman-red group-hover:scale-110 transition-transform">
                {section.icon}
              </span>
              <div className="flex flex-col items-start">
                <span className="text-[10px] font-black tracking-[0.2em] leading-none mb-0.5">{section.role}</span>
                <span className="text-[11px] text-gray-500 group-hover:text-gray-300 transition-colors uppercase">{section.title}</span>
              </div>
            </div>
            {expandedSections[section.role] ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
          </button>

          {expandedSections[section.role] && (
            <div className="flex flex-col ml-10 mt-1 border-l border-gray-800">
              {section.items.map((item) => {
                const isActive = location.pathname === item.path;
                const isDisabled = !item.offline && !isOnline;

                return (
                  <Link
                    key={item.path}
                    to={isDisabled ? '#' : item.path}
                    className={`px-3 py-1.5 text-[11px] uppercase tracking-wider transition-all border-l-2 -ml-[2px] ${
                      isActive
                        ? 'text-white border-hitman-red font-bold bg-hitman-red/5'
                        : 'text-gray-500 border-transparent hover:text-gray-300 hover:border-gray-600'
                    } ${isDisabled ? 'opacity-30 cursor-not-allowed' : ''}`}
                  >
                    {item.name}
                    {isDisabled && <span className="ml-2 text-[8px] italic">[OFFLINE]</span>}
                  </Link>
                );
              })}
            </div>
          )}
        </div>
      ))}
    </nav>
  );
};

export default Navigation;
